{
  "findings": [
    {
      "check_id": "CKV_AWS_8",
      "title": "Ensure all data stored in the Launch configuration or instance Elastic Blocks Store is securely encrypted",
      "resource": "aws_launch_template.changeme_simple_asg_launch_template_nlb",
      "severity": "MEDIUM",
      "explanation": "The launch template does not specify encryption for the root block device or any additional block devices. This could lead to sensitive data being stored unencrypted."
    },
    {
      "check_id": "CKV_AWS_389",
      "title": "Ensure AWS Auto Scaling group launch configuration doesn't have public IP address assignment enabled",
      "resource": "aws_launch_template.changeme_simple_asg_launch_template_nlb",
      "severity": "MEDIUM",
      "explanation": "The launch template does not explicitly disable public IP address assignment. This could expose instances to the public internet unintentionally."
    },
    {
      "check_id": "AVD-AWS-0130",
      "title": "Launch configuration does not require IMDS access to require a token",
      "resource": "aws_launch_template.changeme_simple_asg_launch_template_nlb",
      "severity": "HIGH",
      "explanation": "The launch template does not enforce the use of HTTP tokens for the instance metadata service (IMDS). This could allow unauthorized access to instance metadata."
    }
  ],
  "patched_code": "resource \"aws_launch_template\" \"changeme_simple_asg_launch_template_nlb\" {\n  name                   = \"changeme-simple-asg-launch-template-nlb\"\n  image_id               = data.aws_ami.changeme_amazon_nlb_ami.id\n  instance_type          = \"t2.micro\"\n  vpc_security_group_ids = [aws_security_group.changeme_nlb_aws_security_group.id]\n  user_data              = filebase64(\"${path.module}/user_data.sh\")\n\n  block_device_mappings {\n    device_name = \"/dev/xvda\"\n    ebs {\n      delete_on_termination = true\n      encrypted             = true\n    }\n  }\n\n  network_interfaces {\n    associate_public_ip_address = false\n  }\n\n  metadata_options {\n    http_tokens = \"required\"\n  }\n}",
  "fix_summary": "Added encryption for the root block device to ensure data is securely stored. Disabled public IP address assignment to prevent unintended exposure to the internet. Enforced the use of HTTP tokens for the instance metadata service to enhance security."
}
